def precise(poses,name):
 o=r.get_obs(cameras=[]);seed=o.meta['proprio']['now'][:7];qs=[]
 for pose in poses:
  ans=r.ik({'tip':list(pose)},seed=seed,tol_pos_m=1e-6,tol_rot_rad=1e-5,max_iters=200)
  if not ans['ok']:raise RuntimeError(('IK failed',pose,ans))
  seed=ans['q'];qs.append(seed)
 for i in range(0,len(qs),180):
  run(qs[i:i+180],name,kind='joint_position',video='frames')

def resample(path,step=.00015):
 ds=np.r_[0,np.cumsum(np.linalg.norm(np.diff(path,axis=0),axis=1))];t=np.linspace(0,ds[-1],int(np.ceil(ds[-1]/step))+1)
 return np.stack([np.interp(t,ds,path[:,i]) for i in range(path.shape[1])],axis=1)

def write_path(path,name,practice=False):
 path=np.array(path)
 # Pixel centers of the target to world metres. Main sheet centered at (-.1,0).
 xy=np.column_stack([-.1-(path[:,1]+.5-512)*.00022186,-(path[:,0]+.5-512)*.00022186])
 if practice:
  xy+=np.array([-.055,-.1856])-xy.mean(axis=0)
 q=quat();z=.0192
 move([*xy[0],.045,*q],name+'_approach',speed=.04)
 # precise settling above paper, then vertical contact
 start=[*xy[0],.024,*q];precise([start]*15,name+'_align')
 precise([[*xy[0],zz,*q] for zz in np.linspace(.024,z,25)]+[[*xy[0],z,*q]]*15,name+'_touch')
 dense=resample(xy)
 poses=[[*v,z,*q] for v in dense]+[[*xy[-1],z,*q]]*20
 precise(poses,name+'_draw')
 precise([[*xy[-1],zz,*q] for zz in np.linspace(z,.04,45)],name+'_lift')

if __name__=='__main__' and mode=='practice_o':
 f=np.load(OUT/'o_paths.npz')
 # shared translation for both halves
 paths=[f['a'],f['b']];center=np.vstack(paths).mean(axis=0)
 # practice flag centers each path, so explicitly map both to a shared spot
 for i,p in enumerate(paths):
  p=p.copy();p[:,0]+=(-(-.1856)/.00022186+511.5)-center[0];p[:,1]+=((- .1+.105)/.00022186+511.5)-center[1]
  write_path(p,'practice_o_'+str(i))
 move([-.30,0,.15,0,1,0,0],'park_after_o')
 observe('practice_o_result')
